// Benchmark-only driver: deliberately does not include or alter semiflexible.cu.
#include "../semiflexible.cuh"
#include "../semiflexible_stress.cuh"
#include <thrust/device_vector.h>
#include <chrono>
#include <cstring>
#include <iomanip>
#include <iostream>
#include <vector>

using namespace semiflexible;
using stress3b::Tensor;
using streaming::Sample;
struct Time { double integration=0,stretch=0,bend=0,channels=0,copy=0,diagnostic=0; };
struct Result { Time t; unsigned long long frames=0,hash=1469598103934665603ULL; double wall=0; size_t device=0,host=0; };
static double now(){return std::chrono::duration<double>(std::chrono::steady_clock::now().time_since_epoch()).count();}
static void event(cudaEvent_t a,cudaEvent_t b,double& out){float ms=0;check(cudaEventRecord(b),"benchmark event stop");check(cudaEventSynchronize(b),"benchmark event sync");check(cudaEventElapsedTime(&ms,a,b),"benchmark event elapsed");out+=ms/1000.;}
static unsigned long long fnv(unsigned long long h,const Sample* p,size_t n){auto b=reinterpret_cast<const unsigned char*>(p);for(size_t i=0;i<n*sizeof(Sample);++i)h=(h^b[i])*1099511628211ULL;return h;}
struct Args { int n=8,chains=2048,steps=10000,warmup=100,batch=256; double kappa=10,dt=.000025; std::string mode="batch"; };
static Args parse(int argc,char** argv){ Args x; for(int i=1;i<argc;++i){std::string k=argv[i];if(k=="--help"){std::cout<<"--n N --chains C --steps S --warmup W --batch 256|1024 --kappa 0|10 --mode direct|batch|async\n";std::exit(0);} if(++i==argc)throw std::runtime_error("missing benchmark argument");std::string v=argv[i]; if(k=="--n")x.n=std::stoi(v);else if(k=="--chains")x.chains=std::stoi(v);else if(k=="--steps")x.steps=std::stoi(v);else if(k=="--warmup")x.warmup=std::stoi(v);else if(k=="--batch")x.batch=std::stoi(v);else if(k=="--kappa")x.kappa=std::stod(v);else if(k=="--dt")x.dt=std::stod(v);else if(k=="--mode")x.mode=v;else throw std::runtime_error("unknown benchmark argument");} if(x.n!=8&&x.n!=32)throw std::runtime_error("N must be 8 or 32");if(x.chains<1||x.chains>2048||x.steps<1||x.steps>10000||x.warmup<0||x.warmup>1000||(x.batch!=256&&x.batch!=1024)||(x.kappa!=0&&x.kappa!=10)||(x.mode!="direct"&&x.mode!="batch"&&x.mode!="async"))throw std::runtime_error("benchmark bounds exceeded");return x; }
static Result run(const Args& a){
 const int m=a.n+1,count=m*a.chains; std::vector<real4> initial(count); for(int c=0;c<a.chains;++c)for(int j=0;j<m;++j)initial[c*m+j]=make_real4(real(j),real(c%17)*real(.01),real((c+j)%7)*real(.01),0);
 std::vector<real2> hp(a.n,make_real2(1,30));std::vector<real> ha(m,real(a.kappa));ha.front()=ha.back()=0;
 thrust::device_vector<real4> pos(initial),next(count),force(count); thrust::device_vector<real2> bonds(hp); thrust::device_vector<real> angles; if(a.kappa)angles=ha;
 thrust::device_vector<Tensor> tensor(a.chains);thrust::device_vector<Sample> sample(size_t(a.batch)*a.chains);thrust::device_vector<int> key(1,INT_MAX);thrust::device_vector<Counter> stressKey(1,~Counter(0));
 auto p=[](auto& x){return thrust::raw_pointer_cast(x.data());}; Sample* host=nullptr;check(cudaMallocHost(&host,size_t(a.batch)*a.chains*sizeof(Sample)),"benchmark pinned slab");
 cudaStream_t stream=nullptr;cudaEvent_t ready=nullptr; if(a.mode=="async"){check(cudaStreamCreate(&stream),"benchmark stream");check(cudaEventCreate(&ready),"benchmark ready event");}
 cudaEvent_t start,stop;check(cudaEventCreate(&start),"benchmark event");check(cudaEventCreate(&stop),"benchmark event"); Result r;r.device=pos.capacity()*sizeof(real4)+next.capacity()*sizeof(real4)+force.capacity()*sizeof(real4)+bonds.capacity()*sizeof(real2)+angles.capacity()*sizeof(real)+tensor.capacity()*sizeof(Tensor)+sample.capacity()*sizeof(Sample)+sizeof(int)+sizeof(Counter);r.host=size_t(a.batch)*a.chains*sizeof(Sample);
 auto diagnose=[&](){double t=now();int h;Counter s;check(cudaMemcpy(&h,p(key),sizeof(h),cudaMemcpyDeviceToHost),"benchmark force diagnostic");check(cudaMemcpy(&s,p(stressKey),sizeof(s),cudaMemcpyDeviceToHost),"benchmark stress diagnostic");r.t.diagnostic+=now()-t;if(h!=INT_MAX||s!=~Counter(0))throw std::runtime_error("benchmark diagnostic kernel failure");};
 auto integrate=[&](int step){check(cudaEventRecord(start),"integration start");stretch<<<(count+255)/256,256>>>(p(pos),p(force),p(bonds),count,m,p(key));if(a.kappa)bend<<<(count+255)/256,256>>>(p(pos),p(force),p(angles),count,m,p(key));update<<<(count+255)/256,256>>>(p(pos),p(next),p(force),count,real(a.dt),real(std::sqrt(2*a.dt)),433201,step,p(key));check(cudaGetLastError(),"integration launch");event(start,stop,r.t.integration);diagnose();std::swap(pos,next);};
 size_t fill=0;auto acquire=[&](){check(cudaEventRecord(start),"stretch stress start");stress3b::stretchTensor<<<(a.chains+127)/128,128>>>(p(pos),p(tensor),p(bonds),a.chains,m,p(stressKey));check(cudaGetLastError(),"stretch stress launch");event(start,stop,r.t.stretch);if(a.kappa){check(cudaEventRecord(start),"bend stress start");stress3b::bendTensor<<<(a.chains+127)/128,128>>>(p(pos),p(tensor),nullptr,p(angles),a.chains,m,p(stressKey));check(cudaGetLastError(),"bend stress launch");event(start,stop,r.t.bend);}check(cudaEventRecord(start),"channel start");stress3b::channels<<<(a.chains+127)/128,128>>>(p(tensor),p(sample)+fill*a.chains,a.chains,m,p(stressKey));check(cudaGetLastError(),"channel launch");event(start,stop,r.t.channels);diagnose();++fill;++r.frames;if(a.mode=="direct"||fill==size_t(a.batch)){double t=now();size_t frames=a.mode=="direct"?1:fill;if(a.mode=="async"){check(cudaMemcpyAsync(host,p(sample),frames*a.chains*sizeof(Sample),cudaMemcpyDeviceToHost,stream),"async D2H");check(cudaEventRecord(ready,stream),"async ready");check(cudaEventSynchronize(ready),"async completion");}else check(cudaMemcpy(host,p(sample),frames*a.chains*sizeof(Sample),cudaMemcpyDeviceToHost),"sync D2H");r.t.copy+=now()-t;r.hash=fnv(r.hash,host,frames*a.chains);fill=0;}};
 // Warm-up is deliberately excluded from all reported timers and hashes.
 for(int s=0;s<a.warmup;++s)integrate(s);r.t=Time{};double wall=now();acquire();for(int s=0;s<a.steps;++s){integrate(a.warmup+s);acquire();}if(fill){double t=now();check(cudaMemcpy(host,p(sample),fill*a.chains*sizeof(Sample),cudaMemcpyDeviceToHost),"final partial D2H");r.t.copy+=now()-t;r.hash=fnv(r.hash,host,fill*a.chains);}
 r.wall=now()-wall;cudaFreeHost(host);if(ready)cudaEventDestroy(ready);if(stream)cudaStreamDestroy(stream);cudaEventDestroy(start);cudaEventDestroy(stop);return r;
}
int main(int argc,char** argv){try{Args a=parse(argc,argv);int device;cudaDeviceProp prop{};check(cudaGetDevice(&device),"benchmark device");check(cudaGetDeviceProperties(&prop,device),"benchmark properties");Result r=run(a);double obs=double(r.frames)*a.chains;std::cout<<std::setprecision(17)<<"{\"gpu\":\""<<prop.name<<"\",\"precision_bits\":"<<8*sizeof(real)<<",\"n\":"<<a.n<<",\"chains\":"<<a.chains<<",\"steps\":"<<a.steps<<",\"frames\":"<<r.frames<<",\"mode\":\""<<a.mode<<"\",\"batch\":"<<a.batch<<",\"kappa\":"<<a.kappa<<",\"dt\":"<<a.dt<<",\"frame_hash\":\""<<r.hash<<"\",\"integration_seconds\":"<<r.t.integration<<",\"stretch_seconds\":"<<r.t.stretch<<",\"bend_seconds\":"<<r.t.bend<<",\"channels_seconds\":"<<r.t.channels<<",\"d2h_seconds\":"<<r.t.copy<<",\"diagnostic_seconds\":"<<r.t.diagnostic<<",\"wall_seconds\":"<<r.wall<<",\"stress_frames_per_second\":"<<r.frames/r.wall<<",\"chain_observations_per_second\":"<<obs/r.wall<<",\"integration_ns_per_bead_step\":"<<r.t.integration/(double(a.steps)*a.chains*(a.n+1))*1e9<<",\"overall_ns_per_bead_step\":"<<r.wall/(double(a.steps)*a.chains*(a.n+1))*1e9<<",\"device_bytes\":"<<r.device<<",\"pinned_host_bytes\":"<<r.host<<"}\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
